START TRANSACTION;

INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (366, 'reglas_intro_cards', 'cards', '[{"icon": "BookOpen", "title": "Reglas USGA", "body": "Se aplicarán las reglas U.S.G.A. complementadas con las reglas locales del Campeonato del Club, del 18 al 25 de abril de 2026. El campo se jugará Par 72, Campo San Marcos."}, {"icon": "Trophy", "title": "Formato del torneo", "body": "Primer fin de semana: 36 hoyos Stroke Play (escopetazo 8:00 am); clasifican los mejores 8 de cada categoría. Segundo fin de semana: Match Play — cuartos de final y semifinal entre semana (del 21 al 24 de abril) y la final de cada categoría el 25 de abril."}, {"icon": "ShieldCheck", "title": "Hándicaps y tees de salida", "body": "6 categorías: A y B (salidas azules), C y D (salidas blancas), Seniors (salidas doradas) y Damas (salidas rojas). Todas las categorías jugarán con el 70% de hándicap."}, {"icon": "AlertTriangle", "title": "Juego lento (Regla 6.7)", "body": "Se amonestará al grupo una vez; la segunda ocasión se aplicará castigo (puntos extra en su score total)."}]', 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  content = VALUES(content),
  enabled = 1,
  updated_at = CURRENT_TIMESTAMP;

INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (366, 'reglas_locales', 'accordion', '[{"titulo": "Drops sin castigo", "contenido": "Los indicadores que marcan las yardas en el fairway, válvulas de riego, rehiletes, oasis en el campo, el camino de terracería y áreas en reparación marcadas con pintura blanca y árboles (baby trees) pintados."}, {"titulo": "Hoyo 3", "contenido": "Si su bola cae arriba o dentro de la casa, primero deberá encontrar e identificar su bola; seguido deberá dropear sin castigo un bastón al lugar más cercano en la línea en donde está la bola."}, {"titulo": "Hoyo 4", "contenido": "Si su bola pega en los cables de la corriente eléctrica, deberá tirar otra bola. El poste y el transformador son parte del campo."}, {"titulo": "Hoyo 6", "contenido": "Cualquier bola que quede en el camino, puede jugar su bola desde ahí sin castigo. Si cae en una de las lagunas usará el drop zone que le corresponde; se indicará en un dibujo para mejor información e identificación. Este hoyo se juega con regla local."}, {"titulo": "Hoyo 9", "contenido": "Independientemente de donde repose su bola no hay drop sin castigo, a menos que esté debidamente identificado o marcado por el Comité Organizador."}, {"titulo": "Malla de práctica", "contenido": "La malla de la práctica será OB y estará debidamente señalizada con estacas blancas. Si los cables tensores y las bases de los mismos estorban en el stance o swing se otorgará el free drop. Si la bola pega en algún cable tensor se jugará donde termine su bola."}, {"titulo": "Juego lento (Regla 6.7)", "contenido": "Se amonestará al grupo una vez; la segunda ocasión se aplicará castigo (puntos extra en su score total)."}, {"titulo": "Fuera de límites", "contenido": "Pasando cualquier pared, cerca o estacas blancas."}, {"titulo": "En caso de duda", "contenido": "En cualquier situación: en caso de duda juegue una segunda bola y pregunte al profesional tan pronto como sea posible (termine el hoyo jugando con las dos bolas)."}, {"titulo": "Obstáculos de agua", "contenido": "Obstáculos de agua frontal: estacas amarillas.\\nObstáculos de agua lateral: estacas rojas."}, {"titulo": "Desempates", "contenido": "Para definir un lugar: el primer criterio de desempate será quien obtenga el mejor score el último día de la competencia; de persistir el empate será el score obtenido en los hoyos 10 al 18 del campo, si persiste el empate, del 13 al 18, de continuar, del 16 al 18. Si persistiera el empate se comparará el score del hoyo 18, posteriormente el hoyo 17, hoyo 16, y así sucesivamente hasta el hoyo 1.\\nPara ganar un lugar de los primeros 8 (desempatar el 8vo y 9no lugar): será por muerte súbita en el hoyo que se les asigne por el Comité Organizador; dicho match será con su respectivo hcp del torneo."}, {"titulo": "Zonas drop — Regla local hoyo 3", "contenido": "1. Si su golpe de salida o acercamiento a green queda dentro del área identificada con cal o pintura blanca, su drop deberá ser un bastón fuera del área delimitado de blanco sin acercarse a la bandera.\\n2. Si el golpe de salida o de acercamiento quedara en el techo o área de maquinaria, primero tendrá que encontrar e identificar su bola; seguido, el drop deberá ser en el área de drop más cercana designada para tal efecto, pudiendo ser su drop en área blanca, roja o anaranjada que se indica, dependiendo de donde descanse su bola (ver cuadro)."}, {"titulo": "Zonas drop — Regla local hoyo 6", "contenido": "1. Lagunas ubicadas en tees de salida (identificadas en amarillo): el drop deberá ser en la zona circular identificada en amarillo.\\n2. Lagunas de green (rodeando el green), el drop deberá ser:\\na. Si el golpe de salida no rebasa las áreas marcadas en la ilustración con rojo, el drop será en las zonas circulares identificadas en la ilustración con rojo.\\nb. Si el golpe de salida pasa por cualquier área de green rebasando las líneas marcadas por rojo, independientemente si la bola toque o no tierra, el drop deberá ser en las zonas de drop identificadas en azul, siempre y cuando el golpe de salida no rebase la marca que existe para tal efecto en las orillas de green; si rebasa dicha marca, el drop será en la zona marcada con color morado (ver línea blanca). Existirá una persona del Comité Organizador que auxilie en señalar el área de entrada al agua del golpe de salida.\\nc. Si el golpe de salida queda en el puente posterior al green, el drop será en la zona circular identificada en la ilustración con color amarillo."}, {"titulo": "Derecho de cambios", "contenido": "El Comité de Golf se reserva el derecho de hacer los cambios necesarios para el mejor desarrollo del torneo."}]', 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  content = VALUES(content),
  enabled = 1,
  updated_at = CURRENT_TIMESTAMP;

